import{_ as l,a0 as t,w as o,s as c,ao as d,I as i,x as a,a1 as e,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"如何在 Linux 系统中判断安装、使用了多少内存 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 系统中判断安装、使用了多少内存 | LCTT (201902) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 系统中判断安装、使用了多少内存 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 系统中判断安装、使用了多少内存 | LCTT (201902) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201902/20190207 How to determine how much memory is installed, used on Linux systems","title":"如何在 Linux 系统中判断安装、使用了多少内存","tag":"201902","desc":""},"relativePath":"201902/20190207 How to determine how much memory is installed, used on Linux systems.md","filePath":"[post].md"}'),r={name:"201902/20190207 How to determine how much memory is installed, used on Linux systems.md"};function h(g,s,k,u,b,f){const n=t("Link");return o(),c("div",null,[s[15]||(s[15]=d(`<h1 id="如何在-linux-系统中判断安装、使用了多少内存" tabindex="-1">如何在 Linux 系统中判断安装、使用了多少内存 <a class="header-anchor" href="#如何在-linux-系统中判断安装、使用了多少内存" aria-label="Permalink to “如何在 Linux 系统中判断安装、使用了多少内存”">​</a></h1><blockquote><p>有几个命令可以报告在 Linux 系统上安装和使用了多少内存。根据你使用的命令，你可能会被细节淹没，也可能获得快速简单的答案。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2019/02/memory-100787327-large.jpg" alt=""></p><p>在 Linux 系统中有很多种方法获取有关安装了多少内存的信息及查看多少内存正在被使用。有些命令提供了大量的细节，而其他命令提供了简洁但不一定易于理解的答案。在这篇文章中，我们将介绍一些查看内存及其使用状态的有用的工具。</p><p>在我们开始之前，让我们先来回顾一些基础知识。物理内存和虚拟内存并不是一回事。后者包括配置为交换空间的磁盘空间。交换空间可能包括为此目的特意留出来的分区，以及在创建新的交换分区不可行时创建的用来增加可用交换空间的文件。有些 Linux 命令会提供关于两者的信息。</p><p>当物理内存占满时，交换空间通过提供可以用来存放内存中非活动页的磁盘空间来扩展内存。</p><p><code>/proc/kcore</code> 是在内存管理中起作用的一个文件。这个文件看上去是个普通文件（虽然非常大），但它并不占用任何空间。它就像其他 <code>/proc</code> 下的文件一样是个虚拟文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l /proc/kcore</span></span>
<span class="line"><span>-r--------. 1 root root 140737477881856 Jan 28 12:59 /proc/kcore</span></span></code></pre></div><p>有趣的是，下面查询的两个系统并没有安装相同大小的内存，但 <code>/proc/kcore</code> 的大小却是相同的。第一个系统安装了 4 GB 的内存，而第二个系统安装了 6 GB。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>system1$ ls -l /proc/kcore</span></span>
<span class="line"><span>-r--------. 1 root root 140737477881856 Jan 28 12:59 /proc/kcore</span></span>
<span class="line"><span>system2$ ls -l /proc/kcore</span></span>
<span class="line"><span>-r--------  1 root root 140737477881856 Feb  5 13:00 /proc/kcore</span></span></code></pre></div><p>一种不靠谱的解释说这个文件代表可用虚拟内存的大小（没准要加 4 KB），如果这样，这些系统的虚拟内存可就是 128TB 了！这个数字似乎代表了 64 位系统可以寻址多少内存，而不是当前系统有多少可用内存。在命令行中计算 128 TB 和这个文件大小加上 4 KB 很容易。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ expr 1024 \\* 1024 \\* 1024 \\* 1024 \\* 128</span></span>
<span class="line"><span>140737488355328</span></span>
<span class="line"><span>$ expr 1024 \\* 1024 \\* 1024 \\* 1024 \\* 128 + 4096</span></span>
<span class="line"><span>140737488359424</span></span></code></pre></div><p>另一个用来检查内存的更人性化的命令是 <code>free</code>。它会给出一个易于理解的内存报告。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ free</span></span>
<span class="line"><span>              total        used        free      shared  buff/cache   available</span></span>
<span class="line"><span>Mem:        6102476      812244     4090752       13112     1199480     4984140</span></span>
<span class="line"><span>Swap:       2097148           0     2097148</span></span></code></pre></div><p>使用 <code>-g</code> 选项，<code>free</code> 会以 GB 为单位返回结果。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ free -g</span></span>
<span class="line"><span>              total        used        free      shared  buff/cache   available</span></span>
<span class="line"><span>Mem:              5           0           3           0           1           4</span></span>
<span class="line"><span>Swap:             1           0           1</span></span></code></pre></div><p>使用 <code>-t</code> 选项，<code>free</code> 会显示与无附加选项时相同的值（不要把 <code>-t</code> 选项理解成 TB），并额外在输出的底部添加一行总计数据。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ free -t</span></span>
<span class="line"><span>              total        used        free      shared  buff/cache   available</span></span>
<span class="line"><span>Mem:        6102476      812408     4090612       13112     1199456     4983984</span></span>
<span class="line"><span>Swap:       2097148           0     2097148</span></span>
<span class="line"><span>Total:      8199624      812408     6187760</span></span></code></pre></div><p>当然，你也可以选择同时使用两个选项。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ free -tg</span></span>
<span class="line"><span>              total        used        free      shared  buff/cache   available</span></span>
<span class="line"><span>Mem:              5           0           3           0           1           4</span></span>
<span class="line"><span>Swap:             1           0           1</span></span>
<span class="line"><span>Total:            7           0           5</span></span></code></pre></div><p>如果你尝试用这个报告来解释“这个系统安装了多少内存？”，你可能会感到失望。上面的报告就是在前文说的装有 6 GB 内存的系统上运行的结果。这并不是说这个结果是错的，这就是系统对其可使用的内存的看法。</p><p><code>free</code> 命令也提供了每隔 X 秒刷新显示的选项（下方示例中 X 为 10）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ free -s 10</span></span>
<span class="line"><span>              total        used        free      shared  buff/cache   available</span></span>
<span class="line"><span>Mem:        6102476      812280     4090704       13112     1199492     4984108</span></span>
<span class="line"><span>Swap:       2097148           0     2097148</span></span>
<span class="line"><span></span></span>
<span class="line"><span>              total        used        free      shared  buff/cache   available</span></span>
<span class="line"><span>Mem:        6102476      812260     4090712       13112     1199504     4984120</span></span>
<span class="line"><span>Swap:       2097148           0     2097148</span></span></code></pre></div><p>使用 <code>-l</code> 选项，<code>free</code> 命令会提供高低内存使用信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ free -l</span></span>
<span class="line"><span>              total        used        free      shared  buff/cache   available</span></span>
<span class="line"><span>Mem:        6102476      812376     4090588       13112     1199512     4984000</span></span>
<span class="line"><span>Low:        6102476     2011888     4090588</span></span>
<span class="line"><span>High:             0           0           0</span></span>
<span class="line"><span>Swap:       2097148           0     2097148</span></span></code></pre></div><p>查看内存的另一个选择是 <code>/proc/meminfo</code> 文件。像 <code>/proc/kcore</code> 一样，这也是一个虚拟文件，它可以提供关于安装或使用了多少内存以及可用内存的报告。显然，空闲内存和可用内存并不是同一回事。<code>MemFree</code> 看起来代表未使用的 RAM。<code>MemAvailable</code> 则是对于启动新程序时可使用的内存的一个估计。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ head -3 /proc/meminfo</span></span>
<span class="line"><span>MemTotal: 6102476 kB</span></span>
<span class="line"><span>MemFree: 4090596 kB</span></span>
<span class="line"><span>MemAvailable: 4984040 kB</span></span></code></pre></div><p>如果只想查看内存总计，可以使用下面的命令之一：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk &#39;/MemTotal/ {print $2}&#39; /proc/meminfo</span></span>
<span class="line"><span>6102476</span></span>
<span class="line"><span>$ grep MemTotal /proc/meminfo</span></span>
<span class="line"><span>MemTotal: 6102476 kB</span></span></code></pre></div><p><code>DirectMap</code> 将内存信息分为几类。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep DirectMap /proc/meminfo</span></span>
<span class="line"><span>DirectMap4k: 213568 kB</span></span>
<span class="line"><span>DirectMap2M: 6076416 kB</span></span></code></pre></div><p><code>DirectMap4k</code> 代表被映射成标准 4 k 页的内存大小，<code>DirectMap2M</code> 则显示了被映射为 2 MB 的页的内存大小。</p><p><code>getconf</code> 命令将会提供比我们大多数人想要看到的更多的信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ getconf -a | more</span></span>
<span class="line"><span>LINK_MAX 65000</span></span>
<span class="line"><span>_POSIX_LINK_MAX 65000</span></span>
<span class="line"><span>MAX_CANON 255</span></span>
<span class="line"><span>_POSIX_MAX_CANON 255</span></span>
<span class="line"><span>MAX_INPUT 255</span></span>
<span class="line"><span>_POSIX_MAX_INPUT 255</span></span>
<span class="line"><span>NAME_MAX 255</span></span>
<span class="line"><span>_POSIX_NAME_MAX 255</span></span>
<span class="line"><span>PATH_MAX 4096</span></span>
<span class="line"><span>_POSIX_PATH_MAX 4096</span></span>
<span class="line"><span>PIPE_BUF 4096</span></span>
<span class="line"><span>_POSIX_PIPE_BUF 4096</span></span>
<span class="line"><span>SOCK_MAXBUF</span></span>
<span class="line"><span>_POSIX_ASYNC_IO</span></span>
<span class="line"><span>_POSIX_CHOWN_RESTRICTED 1</span></span>
<span class="line"><span>_POSIX_NO_TRUNC 1</span></span>
<span class="line"><span>_POSIX_PRIO_IO</span></span>
<span class="line"><span>_POSIX_SYNC_IO</span></span>
<span class="line"><span>_POSIX_VDISABLE 0</span></span>
<span class="line"><span>ARG_MAX 2097152</span></span>
<span class="line"><span>ATEXIT_MAX 2147483647</span></span>
<span class="line"><span>CHAR_BIT 8</span></span>
<span class="line"><span>CHAR_MAX 127</span></span>
<span class="line"><span>--More--</span></span></code></pre></div><p>使用类似下面的命令来将其输出精简为指定的内容，你会得到跟前文提到的其他命令相同的结果。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ getconf -a | grep PAGES | awk &#39;BEGIN {total = 1} {if (NR == 1 || NR == 3) total *=$NF} END {print total / 1024&quot; kB&quot;}&#39;</span></span>
<span class="line"><span>6102476 kB</span></span></code></pre></div><p>上面的命令通过将下方输出的第一行和最后一行的值相乘来计算内存。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PAGESIZE                           4096    &lt;==</span></span>
<span class="line"><span>_AVPHYS_PAGES                      1022511</span></span>
<span class="line"><span>_PHYS_PAGES                        1525619 &lt;==</span></span></code></pre></div><p>自己动手计算一下，我们就知道这个值是怎么来的了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ expr 4096 \\* 1525619 / 1024</span></span>
<span class="line"><span>6102476</span></span></code></pre></div><p>显然值得为以上的指令之一设置个 <code>alias</code>。</p><p>另一个具有非常易于理解的输出的命令是 <code>top</code> 。在 <code>top</code> 输出的前五行，你可以看到一些数字显示多少内存正被使用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ top</span></span>
<span class="line"><span>top - 15:36:38 up 8 days, 2:37, 2 users, load average: 0.00, 0.00, 0.00</span></span>
<span class="line"><span>Tasks: 266 total, 1 running, 265 sleeping, 0 stopped, 0 zombie</span></span>
<span class="line"><span>%Cpu(s): 0.2 us, 0.4 sy, 0.0 ni, 99.4 id, 0.0 wa, 0.0 hi, 0.0 si, 0.0 st</span></span>
<span class="line"><span>MiB Mem : 3244.8 total, 377.9 free, 1826.2 used, 1040.7 buff/cache</span></span>
<span class="line"><span>MiB Swap: 3536.0 total, 3535.7 free, 0.3 used. 1126.1 avail Mem</span></span></code></pre></div><p>最后一个命令将会以一个非常简洁的方式回答“系统安装了多少内存？”：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dmidecode -t 17 | grep &quot;Size.*MB&quot; | awk &#39;{s+=$2} END {print s / 1024 &quot;GB&quot;}&#39;</span></span>
<span class="line"><span>6GB</span></span></code></pre></div><p>取决于你想要获取多少细节，Linux 系统提供了许多用来查看系统安装内存以及使用/空闲内存的选择。</p><hr>`,47)),i("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://www.networkworld.com/article/3336174/linux/how-much-memory-is-installed-and-being-used-on-your-linux-systems.html"},{default:p(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3336174/linux/how-much-memory-is-installed-and-being-used-on-your-linux-systems.html",-1)])]),_:1})]),i("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:p(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),e(n,{href:"https://github.com/leommxj"},{default:p(()=>[...s[4]||(s[4]=[a("leommxj",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const C=l(r,[["render",h]]);export{_ as __pageData,C as default};
